            "example": "SELECT CustomerId, COUNT(*) AS OrderCount, SUM(Amount) AS Total\nFROM #LNOrders\nGROUP BY CustomerId\nHAVING SUM(Amount) >= 150\nORDER BY CustomerId;\n-- 1,2,150.00; 2,2,200.00"
